import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), answer = 0;
        for (int i = 0; i < n; i++) {
            String s = Long.toString(sc.nextLong());
            int zeros = 0;
            for (char c : s.toCharArray()) if (c == '0') zeros++;
            answer += zeros % 2;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	answer := 0
	for i := 0; i < n; i++ {
		var v int64
		fmt.Fscan(in, &v)
		answer += strings.Count(strconv.FormatInt(v, 10), "0") % 2
	}
	fmt.Println(answer)
}
